1	/*
2	 * Copyright (c) 2021, salesforce.com, inc.
3	 * All rights reserved.
4	 * SPDX-License-Identifier: BSD-3-Clause
5	 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
6	 */
7	import React from 'react';
8	import { Global, css } from '@emotion/react';
9	import Helmet from 'react-helmet';
10	import { ChakraProvider } from '@salesforce/retail-react-app/app/components/shared/ui';
11	import { getAssetUrl } from '@salesforce/pwa-kit-react-sdk/ssr/universal/utils';
12	import { zimmTokens } from '../../theme/foundation/zimmTokens';
13	
14	// Removes focus for non-keyboard interactions for the whole application
15	import 'focus-visible/dist/focus-visible';
16	
17	import theme from '../../theme';
18	
19	// Inject --zimm-* tokens as raw CSS onto :root via Emotion, bypassing Chakra's
20	// style processor which strips quotes from font-family values.
21	const zimmRootVarsCss = css`
22	  :root {
23	    ${Object.entries(zimmTokens)
24	      .map(([k, v]) => `${k}:${v}`)
25	      .join(';')}
26	  }
27	`;
28	import { MultiSiteProvider, StoreLocatorProvider } from '@salesforce/retail-react-app/app/contexts';
29	import {
30	  resolveSiteFromUrl,
31	  getParamsFromPath,
32	  getSites,
33	  getLocaleByReference,
34	} from '@salesforce/retail-react-app/app/utils/site-utils';
35	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
36	import { getEnvBasePath, slasPrivateProxyPath } from '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths';
37	import { createUrlTemplate } from '@salesforce/retail-react-app/app/utils/url';
38	import createLogger from '@salesforce/pwa-kit-runtime/utils/logger-factory';
39	import { getPasswordlessCallbackUrl } from '@salesforce/retail-react-app/app/utils/auth-utils';
40	
41	import { CommerceApiProvider } from '@salesforce/commerce-sdk-react';
42	import { withReactQuery } from '@salesforce/pwa-kit-react-sdk/ssr/universal/components/with-react-query';
43	import { useCorrelationId } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
44	import { getAppOrigin } from '@salesforce/pwa-kit-react-sdk/utils/url';
45	import { ReactQueryDevtools } from '@tanstack/react-query-devtools';
46	import { generateSfdcUserAgent } from '@salesforce/retail-react-app/app/utils/sfdc-user-agent-utils';
47	import {
48	  DEFAULT_DNT_STATE,
49	  STORE_LOCATOR_RADIUS,
50	  STORE_LOCATOR_RADIUS_UNIT,
51	  STORE_LOCATOR_DEFAULT_COUNTRY,
52	  STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
53	  STORE_LOCATOR_DEFAULT_POSTAL_CODE,
54	  STORE_LOCATOR_DEFAULT_PAGE_SIZE,
55	  STORE_LOCATOR_SUPPORTED_COUNTRIES,
56	} from '@salesforce/retail-react-app/app/constants';
57	import { ContentfulLivePreviewProvider } from '@contentful/live-preview/react';
58	
59	const sfdcUserAgent = generateSfdcUserAgent();
60	
61	type SiteLocale = {
62	  id: string;
63	  alias?: string;
64	  preferredCurrency: string;
65	};
66	
67	// sfccSiteId overrides the SFCC Commerce API siteId for PWA sites whose ID differs from the
68	// SFCC site ID (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
69	type SiteConfig = {
70	  id: string;
71	  sfccSiteId?: string;
72	  alias?: string;
73	  l10n: {
74	    defaultLocale: string;
75	    supportedLocales: SiteLocale[];
76	  };
77	};
78	
79	type AppLocals = {
80	  appConfig?: {
81	    commerceAPI: {
82	      proxyPath: string;
83	      parameters: {
84	        shortCode: string;
85	        clientId: string;
86	        organizationId: string;
87	        siteId?: string;
88	      };
89	    };
90	    login?: {
91	      passwordless?: {
92	        callbackURI?: string;
93	      };
94	    };
95	    einsteinAPI?: unknown;
96	  };
97	  site?: Pick<SiteConfig, 'id' | 'sfccSiteId' | 'alias'>;
98	  locale?: Pick<SiteLocale, 'id' | 'preferredCurrency'>;
99	  buildUrl?: ReturnType<typeof createUrlTemplate>;
100	  originalUrl?: string;
101	};
102	
103	type AppConfigProps = {
104	  children: React.ReactNode;
105	  locals?: AppLocals;
106	};
107	
108	// Preload the only two Futura Round faces the type scale actually uses (400 regular,
109	// 500 medium).
110	//
111	// Emotion 11 inserts <style data-emotion="css-global"> tags inline during
112	// ReactDOMServer.renderToString (which is what pwa-kit-react-sdk's
113	// ssr/server/react-rendering.js uses), so the @font-face rules below ARE present in
114	// the server-rendered HTML without @emotion/server — verified 2026-08-12. They land
115	// in <body> where the <Global> sits in the tree, though, not in <head>: the browser
116	// only discovers them partway through parsing, so the font fetch starts later than it
117	// needs to. This preload moves that discovery into <head> so the fetch begins with
118	// the document.
119	//
120	// Helmet is the only supported route into <head> here: _document lives in
121	// pwa-kit-react-sdk (outside the overrides mechanism) and React 18 does not hoist
122	// <link> elements.
123	function FuturaFontPreload() {
124	  const b = (name: string) => getAssetUrl(`static/fonts/${name}`);
125	  return (
126	    <Helmet>
127	      <link rel="preload" as="font" type="font/woff2" crossOrigin="anonymous" href={b('FuturaRound-Regular.woff2')} />
128	      <link rel="preload" as="font" type="font/woff2" crossOrigin="anonymous" href={b('FuturaRound-Medium.woff2')} />
129	    </Helmet>
130	  );
131	}
132	
133	// Futura Round @font-face — built at render time so getAssetUrl can access
134	// window.Progressive.buildOrigin (not available at module evaluation time).
135	function FuturaFontFaces() {
136	  const b = (name: string) => getAssetUrl(`static/fonts/${name}`);
137	  return (
138	    <Global
139	      styles={css`
140	        @font-face {
141	          font-family: 'Futura Round';
142	          src: url('${b('FuturaRound-Regular.woff2')}') format('woff2');
143	          font-weight: 400;
144	          font-style: normal;
145	          font-display: swap;
146	        }
147	        @font-face {
148	          font-family: 'Futura Round';
149	          src: url('${b('FuturaRound-Oblique.woff2')}') format('woff2');
150	          font-weight: 400;
151	          font-style: italic;
152	          font-display: swap;
153	        }
154	        @font-face {
155	          font-family: 'Futura Round';
156	          src: url('${b('FuturaRound-Light.woff2')}') format('woff2');
157	          font-weight: 300;
158	          font-style: normal;
159	          font-display: swap;
160	        }
161	        @font-face {
162	          font-family: 'Futura Round';
163	          src: url('${b('FuturaRound-LightOblique.woff2')}') format('woff2');
164	          font-weight: 300;
165	          font-style: italic;
166	          font-display: swap;
167	        }
168	        @font-face {
169	          font-family: 'Futura Round';
170	          src: url('${b('FuturaRound-Medium.woff2')}') format('woff2');
171	          font-weight: 500;
172	          font-style: normal;
173	          font-display: swap;
174	        }
175	        @font-face {
176	          font-family: 'Futura Round';
177	          src: url('${b('FuturaRound-MediumOblique.woff2')}') format('woff2');
178	          font-weight: 500;
179	          font-style: italic;
180	          font-display: swap;
181	        }
182	        @font-face {
183	          font-family: 'Futura Round';
184	          src: url('${b('FuturaRound-Demi.woff2')}') format('woff2');
185	          font-weight: 600;
186	          font-style: normal;
187	          font-display: swap;
188	        }
189	        @font-face {
190	          font-family: 'Futura Round';
191	          src: url('${b('FuturaRound-DemiOblique.woff2')}') format('woff2');
192	          font-weight: 600;
193	          font-style: italic;
194	          font-display: swap;
195	        }
196	        @font-face {
197	          font-family: 'Futura Round';
198	          src: url('${b('FuturaRound-Bold.woff2')}') format('woff2');
199	          font-weight: 700;
200	          font-style: normal;
201	          font-display: swap;
202	        }
203	        @font-face {
204	          font-family: 'Futura Round';
205	          src: url('${b('FuturaRound-BoldOblique.woff2')}') format('woff2');
206	          font-weight: 700;
207	          font-style: italic;
208	          font-display: swap;
209	        }
210	      `}
211	    />
212	  );
213	}
214	
215	/**
216	 * Use the AppConfig component to inject extra arguments into the getProps
217	 * methods for all Route Components in the app – typically you'd want to do this
218	 * to inject a connector instance that can be used in all Pages.
219	 *
220	 * You can also use the AppConfig to configure a state-management library such
221	 * as Redux, or Mobx, if you like.
222	 */
223	const AppConfig = ({ children, locals = {} }: AppConfigProps): React.ReactElement => {
224	  const { correlationId } = useCorrelationId();
225	  const headers = {
226	    'correlation-id': correlationId,
227	    sfdc_user_agent: sfdcUserAgent,
228	  };
229	
230	  if (!locals.appConfig) throw new Error('AppConfig: locals.appConfig is required');
231	  const commerceApiConfig = locals.appConfig.commerceAPI;
232	  const locale = locals.locale?.id ?? 'en-US';
233	
234	  const appOrigin = getAppOrigin();
235	  const passwordlessCallbackURI = getPasswordlessCallbackUrl(locals.appConfig?.login?.passwordless?.callbackURI);
236	
237	  const storeLocatorConfig = {
238	    radius: STORE_LOCATOR_RADIUS,
239	    radiusUnit: STORE_LOCATOR_RADIUS_UNIT,
240	    defaultCountry: STORE_LOCATOR_DEFAULT_COUNTRY,
241	    defaultCountryCode: STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
242	    defaultPostalCode: STORE_LOCATOR_DEFAULT_POSTAL_CODE,
243	    defaultPageSize: STORE_LOCATOR_DEFAULT_PAGE_SIZE,
244	    supportedCountries: STORE_LOCATOR_SUPPORTED_COUNTRIES,
245	  };
246	
247	  // Set absolute uris for CommerceApiProvider proxies and callbacks
248	  const redirectURI = `${appOrigin}${getEnvBasePath()}/callback`;
249	  const proxy = `${appOrigin}${getEnvBasePath()}${commerceApiConfig.proxyPath}`;
250	  const slasPrivateClientProxyEndpoint = `${appOrigin}${getEnvBasePath()}${slasPrivateProxyPath}`;
251	
252	  return (
253	    <CommerceApiProvider
254	      shortCode={commerceApiConfig.parameters.shortCode}
255	      clientId={commerceApiConfig.parameters.clientId}
256	      organizationId={commerceApiConfig.parameters.organizationId}
257	      siteId={locals.site?.sfccSiteId ?? locals.site?.id ?? ''}
258	      locale={locale}
259	      currency={locals.locale?.preferredCurrency ?? ''}
260	      redirectURI={redirectURI}
261	      proxy={proxy}
262	      headers={headers}
263	      defaultDnt={DEFAULT_DNT_STATE}
264	      logger={createLogger({ packageName: 'commerce-sdk-react' })}
265	      passwordlessLoginCallbackURI={passwordlessCallbackURI}
266	      // Set 'enablePWAKitPrivateClient' to true to use SLAS private client login flows.
267	      // Make sure to also enable useSLASPrivateClient in ssr.js when enabling this setting.
268	      enablePWAKitPrivateClient={true}
269	      privateClientProxyEndpoint={slasPrivateClientProxyEndpoint}
270	      // Uncomment 'hybridAuthEnabled' if the current site has Hybrid Auth enabled. Do NOT set this flag for hybrid storefronts using Plugin SLAS.
271	      // hybridAuthEnabled={true}
272	    >
273	      <MultiSiteProvider site={locals.site} locale={locals.locale} buildUrl={locals.buildUrl}>
274	        <StoreLocatorProvider config={storeLocatorConfig}>
275	          <ContentfulLivePreviewProvider locale={locale} enableInspectorMode enableLiveUpdates>
276	            <ChakraProvider theme={theme}>
277	              <Global styles={zimmRootVarsCss} />
278	              <FuturaFontPreload />
279	              <FuturaFontFaces />
280	              {children}
281	            </ChakraProvider>
282	          </ContentfulLivePreviewProvider>
283	        </StoreLocatorProvider>
284	      </MultiSiteProvider>
285	      <ReactQueryDevtools />
286	    </CommerceApiProvider>
287	  );
288	};
289	
290	AppConfig.restore = (locals: AppLocals = {}): void => {
291	  const path =
292	    typeof window === 'undefined' ? locals.originalUrl ?? '/' : `${window.location.pathname}${window.location.search}`;
293	
294	  // resolveSiteFromUrl only matches a site alias/ID in the URL. When url.site is 'none' the site
295	  // segment is absent, so it always falls back to the defaultSite. In that case, find the real site
296	  // by matching the locale alias from the URL against each site's supportedLocales.
297	  const defaultResolved = resolveSiteFromUrl(path);
298	  const { localeRef } = getParamsFromPath(path);
299	  type SupportedLocale = { id: string; alias?: string };
300	  // sfccSiteId overrides the SFCC Commerce API siteId for PWA sites that don't share their ID
301	  // with their SFCC counterpart (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
302	  type Site = {
303	    id: string;
304	    sfccSiteId?: string;
305	    alias?: string;
306	    l10n: { defaultLocale: string; supportedLocales: SupportedLocale[] };
307	  };
308	  const site: Site = localeRef
309	    ? (getSites() as Site[]).find((s) =>
310	        s.l10n.supportedLocales.some((l) => l.alias === localeRef || l.id === localeRef),
311	      ) ?? defaultResolved
312	    : defaultResolved;
313	
314	  // resolveLocaleFromUrl also calls resolveSiteFromUrl internally, so it would return the wrong
315	  // site too. Resolve the locale directly from the site we already found above.
316	  const locale = (getLocaleByReference(site, localeRef ?? site.l10n.defaultLocale) ??
317	    getLocaleByReference(site, site.l10n.defaultLocale)) as SiteLocale;
318	
319	  const { app: appConfig } = getConfig() as { app: NonNullable<AppLocals['appConfig']> };
320	  const apiConfig = {
321	    ...appConfig.commerceAPI,
322	    einsteinConfig: appConfig.einsteinAPI,
323	  };
324	
325	  apiConfig.parameters.siteId = site.sfccSiteId ?? site.id;
326	
327	  locals.buildUrl = createUrlTemplate(appConfig, site.alias || site.id, locale.alias || locale.id);
328	  locals.site = site;
329	  locals.locale = locale;
330	  locals.appConfig = appConfig;
331	};
332	
333	AppConfig.freeze = (): undefined => undefined;
334	
335	AppConfig.extraGetPropsArgs = (locals: AppLocals = {}): Record<string, unknown> => {
336	  return {
337	    buildUrl: locals.buildUrl,
338	    site: locals.site,
339	    locale: locals.locale,
340	  };
341	};
342	
343	const isServerSide = typeof window === 'undefined';
344	
345	// Recommended settings for PWA-Kit usages.
346	// NOTE: they will be applied on both server and client side.
347	// retry is always disabled on server side regardless of the value from the options
348	const options = {
349	  queryClientConfig: {
350	    defaultOptions: {
351	      queries: {
352	        retry: false,
353	        refetchOnWindowFocus: false,
354	        staleTime: 10 * 1000,
355	        ...(isServerSide ? { retryOnMount: false } : {}),
356	      },
357	      mutations: {
358	        retry: false,
359	      },
360	    },
361	  },
362	};
363	
364	export default withReactQuery(AppConfig, options);
365

