    39	  export function useServerContext(): {
    40	    req?: any;
    41	    res?: ServerResponse;
    42	  };
    43	  export function useCorrelationId(): { correlationId: string };
    44	}
    45	
    46	declare module '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths' {
    47	  export const getEnvBasePath: () => string;
    48	  export const slasPrivateProxyPath: string;
    49	}
    50	
    51	declare module '@salesforce/pwa-kit-runtime/utils/logger-factory' {
    52	  const createLogger: (opts: { packageName: string }) => any;
    53	  export default createLogger;
    54	}
    55	
    56	declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/components/with-react-query' {
    57	  export function withReactQuery(Component: any, options?: any): any;
    58	}
    59	
    60	declare module '@salesforce/pwa-kit-react-sdk/utils/url' {
    61	  export function getAppOrigin(): string;
    62	}
    63	
    64	declare module '@loadable/component' {
    65	  const loadable: (fn: () => Promise<any>, opts?: any) => any;
    66	  export default loadable;
    67	}
    68	
    69	// react-helmet ships no types and @types/react-helmet is not installed. It is a direct
    70	// dependency of @salesforce/pwa-kit-react-sdk (required by ssr/server/react-rendering.js,
    71	// which calls Helmet.renderStatic()), so it resolves without adding it to package.json.
    72	declare module 'react-helmet' {
    73	  import type { ComponentType, ReactNode } from 'react';
    74	  const Helmet: ComponentType<{ children?: ReactNode }>;
    75	  export default Helmet;
    76	}
    77	
    78	// Static asset imports (webpack url-loader / asset modules)
    79	declare module '*.svg' {
    80	  const src: string;
    81	  export default src;
    82	}
    83	
    84	// Catch-all for all other @salesforce/retail-react-app subpaths not declared above.
    85	declare module '@salesforce/retail-react-app/*';
    86	
    87	// @vitejs/plugin-react uses package exports only (no root index.d.ts), which
    88	// TypeScript 4.9 with moduleResolution:node cannot resolve. Minimal shim — the
    89	// actual Plugin return type depends on vite types that are equally unreachable
    90	// from TS 4.9. Once the project upgrades to TS 5+ this declaration can be removed.
    91	declare module '@vitejs/plugin-react' {
    92	  interface Options {
    93	    include?: string | RegExp | Array<string | RegExp>;
    94	    exclude?: string | RegExp | Array<string | RegExp>;
    95	    jsxImportSource?: string;
    96	  }
    97	  // Return typed as any: Plugin from vite is not resolvable under moduleResolution:node.
    98	  function react(options?: Options): any;
    99	  export default react;
   100	}

