import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { Box, Flex, Heading, SimpleGrid, Stack, Text } from '@chakra-ui/react';
import { colors } from '../../theme/foundation/colour';

/**
 * Visual reference for every brand colour token, grouped exactly as
 * `theme/foundation/colour.ts` groups them (primitives first, then semantic
 * aliases). Swatches are decorative — the token path and literal value are
 * rendered as text beside each one, so the story never relies on colour alone.
 */

/**
 * Most groups are one level deep (`grey.900`), but `action` nests a second level
 * (`action.primary.bgDefault`), so token paths are flattened recursively rather
 * than assumed flat.
 */
function flattenTokens(node: unknown, prefix: string): Array<[string, string]> {
  if (typeof node === 'string') {
    return [[prefix, node]];
  }

  if (node !== null && typeof node === 'object') {
    return Object.entries(node as Record<string, unknown>).flatMap(([key, value]) =>
      flattenTokens(value, prefix ? `${prefix}.${key}` : key),
    );
  }

  return [];
}
